package com.agriquest.ui.sound

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.media.SoundPool
import com.agriquest.R
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/** Short game sounds (original, generated by scripts/generate-sounds.py) and the optional garden ambience. */
enum class GameSound(val resId: Int) {
    WATER(R.raw.sfx_water),
    FAN(R.raw.sfx_fan),
    LIGHT(R.raw.sfx_light),
    SUCCESS(R.raw.sfx_success),
    TAP(R.raw.sfx_tap)
}

object GameSounds {
    private const val PREFS = "agriquest_sound"
    private const val KEY_MUTED = "muted"
    private const val AMBIENT_VOLUME = 0.18f

    private var pool: SoundPool? = null
    private val loaded = mutableMapOf<GameSound, Int>()
    private val ready = mutableSetOf<Int>()
    private var ambient: MediaPlayer? = null
    private var appContext: Context? = null
    private var ambientWanted = false

    private val _muted = MutableStateFlow(false)
    val muted: StateFlow<Boolean> = _muted.asStateFlow()

    /** Loads the sounds once; safe to call again. */
    fun init(context: Context) {
        if (pool != null) return
        val app = context.applicationContext
        appContext = app
        _muted.value = app.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getBoolean(KEY_MUTED, false)
        val attributes = AudioAttributes.Builder()
            .setUsage(AudioAttributes.USAGE_GAME)
            .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
            .build()
        val soundPool = SoundPool.Builder().setMaxStreams(4).setAudioAttributes(attributes).build()
        soundPool.setOnLoadCompleteListener { _, sampleId, status -> if (status == 0) ready += sampleId }
        GameSound.entries.forEach { loaded[it] = soundPool.load(app, it.resId, 1) }
        pool = soundPool
    }

    fun play(sound: GameSound, volume: Float = 0.9f) {
        if (_muted.value) return
        val id = loaded[sound] ?: return
        if (id in ready) pool?.play(id, volume, volume, 1, 0, 1f)
    }

    fun setMuted(muted: Boolean) {
        _muted.value = muted
        appContext?.getSharedPreferences(PREFS, Context.MODE_PRIVATE)?.edit()?.putBoolean(KEY_MUTED, muted)?.apply()
        if (muted) pauseAmbient() else if (ambientWanted) startAmbient()
    }

    /** Quiet looping garden sound while the game screen is visible. */
    fun startAmbient() {
        ambientWanted = true
        if (_muted.value) return
        val context = appContext ?: return
        val player = ambient ?: runCatching {
            MediaPlayer.create(context, R.raw.ambient_garden)?.apply {
                isLooping = true
                setVolume(AMBIENT_VOLUME, AMBIENT_VOLUME)
            }
        }.getOrNull()?.also { ambient = it } ?: return
        if (!player.isPlaying) runCatching { player.start() }
    }

    fun stopAmbient() {
        ambientWanted = false
        pauseAmbient()
    }

    private fun pauseAmbient() {
        ambient?.let { if (it.isPlaying) runCatching { it.pause() } }
    }
}
